private static final char[][] MESSAGE_TYPES = TypeConstants.JAVA_LANG_STRING;
private static final char[][] CAUSE_TYPES = TypeConstants.JAVA_LANG_THROWABLE;

/**
 * Creates a null literal cast to the given type, so that overload resolution cannot be ambiguous if
 * another constructor with the same number of reference parameters exists, e.g. from {@code @AllArgsConstructor}.
 */
private static Expression createCastToNull(EclipseNode typeNode, char[][] typeName, int pS, int pE, ASTNode source) {
	long[] poss = new long[typeName.length];
	Arrays.fill(poss, (long) pS << 32 | pE);
	TypeReference typeRef = new QualifiedTypeReference(typeName, poss);
	setGeneratedBy(typeRef, source);
	CastExpression cast = new CastExpression(new NullLiteral(pS, pE), typeRef);
	cast.sourceStart = pS;
	cast.sourceEnd = pE;
	setGeneratedBy(cast, source);
	return cast;
}

